/* Off the Hook — Industrial crisis-room theme: steel, concrete, alarm-amber/red. */
.hostage-sim-container {
    padding: 28px;
    background: #121417;
    background-image: linear-gradient(180deg, #15181c 0%, #101215 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e6e9ee;
}
.hostage-sim-header {
    background: linear-gradient(135deg, #1c1f24 0%, #24272d 100%);
    color: #f2f4f7;
    padding: 32px 36px;
    border-radius: 6px;
    margin-bottom: 24px;
    border-left: 6px solid #e0392b;
    box-shadow: 0 8px 26px rgba(0,0,0,0.45);
    position: relative;
    overflow: hidden;
}
.hostage-sim-header::after {
    content: "";
    position: absolute;
    inset: 0;
    background: repeating-linear-gradient(45deg, rgba(224,57,43,0.05) 0 12px, transparent 12px 24px);
    pointer-events: none;
}
.hostage-sim-header-tag {
    display: inline-block;
    background: rgba(224,57,43,0.18);
    color: #ff8d80;
    padding: 4px 12px;
    border-radius: 4px;
    font-size: 0.74rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    margin-bottom: 12px;
    font-weight: 700;
    position: relative;
}
.hostage-sim-header h1 {
    font-size: 2rem;
    font-weight: 800;
    margin: 0 0 10px 0;
    letter-spacing: -0.01em;
    position: relative;
}
.hostage-sim-subtitle {
    margin: 0;
    font-size: 1.02rem;
    color: #b9c0cc;
    max-width: 760px;
    line-height: 1.5;
    position: relative;
}
.hostage-sim-period-counter {
    background: #1a1d22;
    border: 1px solid #2c313a;
    border-radius: 6px;
    padding: 14px 22px;
    margin-bottom: 24px;
    font-size: 0.95rem;
    color: #9aa3b2;
    font-weight: 500;
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
}
.hostage-sim-period-counter span {
    font-weight: 700;
    color: #e6e9ee;
}
.hostage-sim-round-name {
    margin-left: 14px;
    color: #f2a900;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    font-size: 0.85rem;
}
.hostage-sim-clock {
    margin-left: auto;
    color: #ff8d80 !important;
    font-variant-numeric: tabular-nums;
    background: rgba(224,57,43,0.12);
    padding: 4px 12px;
    border-radius: 4px;
    font-size: 0.85rem;
}
.hostage-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
}
.hostage-sim-status-card {
    background: #1a1d22;
    border: 1px solid #2c313a;
    border-radius: 6px;
    padding: 22px 20px;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.hostage-sim-status-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 20px rgba(0,0,0,0.4);
}
.hostage-sim-card-primary {
    border-top: 4px solid #2bb25e;
    background: linear-gradient(180deg, #18241c 0%, #1a1d22 100%);
}
.hostage-sim-card-loss {
    border-top: 4px solid #e0392b;
    background: linear-gradient(180deg, #241818 0%, #1a1d22 100%);
}
.hostage-sim-label {
    color: #8a93a3;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-weight: 700;
    margin-bottom: 10px;
}
.hostage-sim-value {
    font-size: 2.5rem;
    font-weight: 800;
    color: #f2f4f7;
    line-height: 1;
    margin-bottom: 6px;
    font-variant-numeric: tabular-nums;
}
.hostage-sim-card-primary .hostage-sim-value {
    color: #4fd683;
}
.hostage-sim-card-loss .hostage-sim-value {
    color: #ff6b5c;
}
.hostage-sim-sublabel {
    color: #7c8595;
    font-size: 0.78rem;
}
.hostage-sim-briefing {
    background: #1c1f24;
    border: 1px solid #3a2f22;
    border-left: 5px solid #f2a900;
    border-radius: 6px;
    padding: 22px 24px;
    margin-bottom: 24px;
    display: flex;
    gap: 18px;
    align-items: flex-start;
}
.hostage-sim-briefing-icon {
    font-size: 2rem;
    line-height: 1;
    flex-shrink: 0;
}
.hostage-sim-briefing-body {
    flex: 1;
}
.hostage-sim-briefing-title {
    font-size: 1.08rem;
    font-weight: 800;
    color: #f7d27a;
    margin-bottom: 8px;
}
.hostage-sim-briefing-text {
    color: #ccd2dc;
    line-height: 1.6;
    font-size: 0.95rem;
}
.hostage-sim-briefing-text strong {
    color: #f7d27a;
}
.hostage-sim-controls {
    background: #1a1d22;
    border: 1px solid #2c313a;
    border-radius: 6px;
    padding: 26px;
    margin-bottom: 24px;
}
.hostage-sim-controls h3 {
    font-size: 1.1rem;
    font-weight: 800;
    color: #f2f4f7;
    margin: 0 0 18px 0;
    padding-bottom: 12px;
    border-bottom: 1px solid #2c313a;
}
.hostage-sim-panel {
    margin-bottom: 8px;
}
.hostage-sim-controls label {
    display: block;
    font-size: 0.85rem;
    font-weight: 600;
    color: #c2c9d4;
    margin-bottom: 6px;
    margin-top: 16px;
}
.hostage-sim-controls input[type="number"],
.hostage-sim-controls input[type="text"],
.hostage-sim-controls select {
    width: 100%;
    background-color: #0f1114;
    border: 1px solid #353b45;
    color: #e6e9ee;
    border-radius: 4px;
    padding: 10px 12px;
    font-size: 0.95rem;
    font-family: inherit;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.hostage-sim-controls select option {
    background-color: #0f1114;
    color: #e6e9ee;
}
.hostage-sim-controls input[type="number"]:focus,
.hostage-sim-controls input[type="text"]:focus,
.hostage-sim-controls select:focus {
    outline: none;
    border-color: #f2a900;
    box-shadow: 0 0 0 3px rgba(242,169,0,0.18);
}
.hostage-sim-controls input[type="range"] {
    width: 100%;
    accent-color: #e0392b;
    margin-top: 8px;
}
.hostage-sim-range-readout {
    font-size: 0.85rem;
    color: #9aa3b2;
    margin-top: 6px;
}
.hostage-sim-range-readout span:last-child {
    color: #ff8d80;
    font-weight: 700;
}
.hostage-sim-controls .btn {
    margin-top: 24px;
    padding: 12px 24px;
    border-radius: 4px;
    font-weight: 700;
    font-size: 0.95rem;
    letter-spacing: 0.02em;
    border: none;
    transition: background 0.2s ease, transform 0.15s ease;
}
.hostage-sim-controls .btn-primary {
    background: #e0392b;
    color: #ffffff;
}
.hostage-sim-controls .btn-primary:hover {
    background: #f24336;
    transform: translateY(-1px);
}
.hostage-sim-controls .btn-outline-secondary {
    background: transparent;
    color: #9aa3b2;
    border: 1px solid #353b45;
    margin-left: 10px;
}
.hostage-sim-controls .btn-outline-secondary:hover {
    background: #22262c;
    color: #e6e9ee;
}
.hostage-sim-coach {
    background: linear-gradient(135deg, #1c1f24 0%, #262a31 100%);
    color: #e6e9ee;
    border-radius: 6px;
    padding: 22px 26px;
    margin-bottom: 24px;
    border-left: 5px solid #e0392b;
}
.hostage-sim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    color: #ff8d80;
    font-weight: 800;
    margin-bottom: 10px;
}
.hostage-sim-coach-body {
    line-height: 1.6;
    font-size: 0.98rem;
    color: #e6e9ee;
}
.hostage-sim-coach-body strong {
    color: #f7d27a;
}
.hostage-sim-history {
    background: #1a1d22;
    border: 1px solid #2c313a;
    border-radius: 6px;
    padding: 24px;
    margin-bottom: 24px;
    overflow-x: auto;
}
.hostage-sim-history h3 {
    font-size: 1.05rem;
    font-weight: 800;
    color: #f2f4f7;
    margin: 0 0 14px 0;
}
.hostage-sim-history table {
    margin-bottom: 0;
    color: #e6e9ee;
    width: 100%;
}
.hostage-sim-history table th {
    background: #15181c;
    color: #9aa3b2;
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    font-weight: 700;
    border-bottom: 2px solid #2c313a;
    padding: 10px 12px;
}
.hostage-sim-history table td {
    color: #d4d9e1;
    font-size: 0.9rem;
    padding: 10px 12px;
    border-bottom: 1px solid #22262c;
}
.hostage-sim-chart {
    background: #1a1d22;
    border: 1px solid #2c313a;
    border-radius: 6px;
    padding: 24px;
    margin-bottom: 24px;
    height: 380px;
}
.hostage-sim-chart h3 {
    font-size: 1.05rem;
    font-weight: 800;
    color: #f2f4f7;
    margin: 0 0 14px 0;
}
.hostage-sim-chart canvas {
    max-height: 300px;
}
@media (max-width: 768px) {
    .hostage-sim-container { padding: 16px; }
    .hostage-sim-header { padding: 24px 22px; }
    .hostage-sim-header h1 { font-size: 1.5rem; }
    .hostage-sim-status-cards { grid-template-columns: repeat(2, 1fr); }
    .hostage-sim-value { font-size: 1.9rem; }
    .hostage-sim-period-counter { flex-wrap: wrap; }
    .hostage-sim-clock { margin-left: 0; width: 100%; margin-top: 6px; text-align: center; }
    .hostage-sim-round-name { margin-left: 0; }
}


/* FIX v1.1.0 — completion / negotiation-debrief screen */
.oh-completion { padding: 10px 6px; text-align: center; }
.oh-completion-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #64748b; margin-bottom: 6px; }
.oh-completion-verdict { font-size: 20px; font-weight: 700; color: #0f172a; margin-bottom: 8px; }
.oh-completion-score { font-size: 16px; color: #0f172a; margin-bottom: 14px; }
.oh-completion-score strong { color: #0d9488; }
.oh-completion-metrics { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-bottom: 16px; }
.oh-completion-metric { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; padding: 8px 12px; background: #f1f5f9; border-radius: 8px; min-width: 100px; }
.oh-completion-metric span { font-size: 11px; letter-spacing: .03em; text-transform: uppercase; color: #64748b; }
.oh-completion-metric strong { font-size: 16px; color: #0f172a; }
.oh-completion-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 680px; text-align: left; }
.oh-completion-insights li { padding: 9px 13px; margin-bottom: 7px; background: #f0fdfa; border-left: 3px solid #0d9488; border-radius: 4px; color: #1e293b; font-size: 13px; }

