(function() {
    'use strict';

    class HostageAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Off the Hook`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // The concept's truth: the chair is fighting for trust/respect, not a wage number.
            this.TRUE_NEED = `trust`;
            this.TRUE_POSITION = `relocation`;
            // €95k/h line-down cost; baseline ~1h already lost before the team acts.
            this.HOURLY_LOSS = 0.095; // € millions per hour
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    deescalation: 20,
                    trust: 55,
                    selfreg: 60,
                    hoursDown: 1,           // ~1h already lost at 06:40 before management moves
                    productionLoss: 0.095,  // € millions
                    penaltyTriggered: false,
                    contagion: false,
                    deescHistory: [20],
                    trustHistory: [55],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    need: `trust`,
                    position: `relocation`,
                    threatReaction: 60,
                    opening: `acknowledge`,
                    listenShare: 60,
                    setting: `floor`,
                    reframe: `shared`,
                    move: `taskforce`,
                    spike: `stay`,
                    relocation: `joint`,
                    return: `now_process`,
                    comms: `joint`,
                    selfmgmt: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const need = document.getElementById(`needInput`);
                const pos = document.getElementById(`positionInput`);
                const thr = document.getElementById(`threatReactionInput`);
                if (need) decisions.need = need.value;
                if (pos) decisions.position = pos.value;
                if (thr) decisions.threatReaction = parseInt(thr.value, 10);
                if (!Number.isFinite(decisions.threatReaction) || decisions.threatReaction < 0 || decisions.threatReaction > 100) {
                    warn(`warn_threat_range`); return false;
                }
            } else if (round === 2) {
                const op = document.getElementById(`openingInput`);
                const ls = document.getElementById(`listenShareInput`);
                const se = document.getElementById(`settingInput`);
                if (op) decisions.opening = op.value;
                if (se) decisions.setting = se.value;
                if (ls) decisions.listenShare = parseInt(ls.value, 10);
                if (!Number.isFinite(decisions.listenShare) || decisions.listenShare < 0 || decisions.listenShare > 100) {
                    warn(`warn_listen_range`); return false;
                }
            } else if (round === 3) {
                const rf = document.getElementById(`reframeInput`);
                const mv = document.getElementById(`moveInput`);
                const sp = document.getElementById(`spikeInput`);
                if (rf) decisions.reframe = rf.value;
                if (mv) decisions.move = mv.value;
                if (sp) decisions.spike = sp.value;
            } else if (round === 4) {
                const rl = document.getElementById(`relocationInput`);
                const rt = document.getElementById(`returnInput`);
                const cm = document.getElementById(`commsInput`);
                const sm = document.getElementById(`selfmgmtInput`);
                if (rl) decisions.relocation = rl.value;
                if (rt) decisions.return = rt.value;
                if (cm) decisions.comms = cm.value;
                if (sm) decisions.selfmgmt = parseInt(sm.value, 10);
                if (!Number.isFinite(decisions.selfmgmt) || decisions.selfmgmt < 0 || decisions.selfmgmt > 100) {
                    warn(`warn_selfmgmt_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let deescDelta = 0, trustDelta = 0, selfregDelta = 0;
            let hoursThisRound = 0;     // line-down hours added this round
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            // Carry the prior self-regulation: a hostage to your own emotion blunts everything.
            const calmFactor = 0.6 + (ds.selfreg / 100) * 0.5; // 0.6 .. 1.1

            if (round === 1) {
                // Diagnose the underlying NEED vs the stated POSITION + own your threat reaction.
                hoursThisRound = 2; // diagnosis takes ~2h of the line being down
                if (d.need === this.TRUE_NEED) {
                    deescDelta += 14; trustDelta += 6; coachKey = `coach_r1_need_right`;
                } else if (d.need === `jobs`) {
                    deescDelta += 4; coachKey = `coach_r1_need_jobs`;
                } else {
                    deescDelta -= 4; trustDelta -= 4; coachKey = `coach_r1_need_wrong`;
                }
                if (d.position === this.TRUE_POSITION) {
                    deescDelta += 4;
                } else {
                    deescDelta -= 2;
                }
                // Self-mastery: naming a high threat reaction (>=60) and choosing to regulate it raises self-reg.
                if (d.threatReaction >= 60) {
                    selfregDelta += 12; // honest self-awareness is the first move
                    coachKey = (d.need === this.TRUE_NEED) ? `coach_r1_aware` : coachKey;
                } else if (d.threatReaction <= 20) {
                    selfregDelta -= 6; // false calm / denial of the hostage response
                }
                summaryKey = (d.need === this.TRUE_NEED) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Bond before bargain: acknowledge the rupture, listen, meet him with dignity.
                hoursThisRound = 1.5;
                switch (d.opening) {
                    case `acknowledge`:
                        deescDelta += 16; trustDelta += 16; coachKey = `coach_r2_acknowledge`; break;
                    case `shared`:
                        deescDelta += 10; trustDelta += 9; coachKey = `coach_r2_shared`; break;
                    case `rights`:
                        deescDelta -= 14; trustDelta -= 16; selfregDelta -= 6; coachKey = `coach_r2_rights`; break;
                    case `process`:
                        deescDelta += 2; trustDelta -= 2; coachKey = `coach_r2_process`; break;
                }
                // Listening: bonding means he talks more than you. Sweet spot ~70%.
                const gap = Math.abs(d.listenShare - 70);
                if (gap <= 10) { trustDelta += 8; deescDelta += 5; }
                else if (d.listenShare < 50) { trustDelta -= 8; deescDelta -= 5; coachKey = `coach_r2_overtalk`; }
                // Setting: walking onto the floor alone signals courage + respect (secure base).
                if (d.setting === `floor`) { deescDelta += 6; trustDelta += 5; }
                else if (d.setting === `megaphone`) { deescDelta -= 6; trustDelta -= 4; }
                else if (d.setting === `office`) { deescDelta -= 8; trustDelta -= 6; coachKey = `coach_r2_office`; }
                summaryKey = (d.opening === `acknowledge` || d.opening === `shared`) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Reframe threat -> shared problem, choose the unlocking move, hold under the spike.
                hoursThisRound = 1.5;
                if (d.reframe === `shared`) { deescDelta += 12; trustDelta += 6; }
                else if (d.reframe === `zerosum`) { deescDelta -= 10; trustDelta -= 6; coachKey = `coach_r3_zerosum`; }
                else if (d.reframe === `legal`) { deescDelta -= 4; trustDelta -= 4; }

                // Bonding gate: an unlocking move only lands if trust is already there.
                const bonded = ds.trust >= 60;
                switch (d.move) {
                    case `taskforce`:
                        deescDelta += 12; trustDelta += 10; coachKey = `coach_r3_taskforce`; break;
                    case `pause`:
                        deescDelta += 14; trustDelta += 12; coachKey = `coach_r3_pause`; break;
                    case `openbook`:
                        deescDelta += 8; trustDelta += 14; coachKey = `coach_r3_openbook`; break;
                    case `phased`:
                        // Tabling substance early — fine only if bonded; otherwise it can't land.
                        if (bonded) { deescDelta += 9; trustDelta += 3; coachKey = `coach_r3_phased_ok`; }
                        else { deescDelta -= 6; trustDelta -= 4; coachKey = `coach_r3_phased_rush`; }
                        break;
                    case `split`:
                        // Casting the chair as an enemy to out-maneuver — Common Error 2.
                        deescDelta -= 12; trustDelta -= 18; coachKey = `coach_r3_split`; break;
                }
                if (!bonded && (d.move === `taskforce` || d.move === `pause` || d.move === `openbook`)) {
                    // A good move offered before the bond is half-wasted.
                    deescDelta = Math.round(deescDelta * 0.5);
                    coachKey = `coach_r3_unbonded`;
                }

                // The emotional spike: stay calm (secure base) vs become a hostage to his emotion.
                if (d.spike === `stay`) { selfregDelta += 12; deescDelta += 6; trustDelta += 5; }
                else if (d.spike === `match`) { selfregDelta -= 16; deescDelta -= 12; trustDelta -= 10; coachKey = `coach_r3_match`; }
                else if (d.spike === `retreat`) { selfregDelta -= 4; deescDelta -= 6; }
                summaryKey = (d.reframe === `shared` && d.spike === `stay`) ? `sum_r3_good` : `sum_r3_weak`;
            } else if (round === 4) {
                // Land the agreement: restore trust, not just compliance, before 14:00.
                hoursThisRound = 1.5;
                if (d.relocation === `joint`) { deescDelta += 12; trustDelta += 12; }
                else if (d.relocation === `off`) { deescDelta += 8; trustDelta += 2; coachKey = `coach_r4_off`; }
                else if (d.relocation === `proceed`) { deescDelta -= 16; trustDelta -= 20; coachKey = `coach_r4_proceed`; }

                if (d.return === `now_process`) { deescDelta += 14; trustDelta += 10; coachKey = `coach_r4_process`; }
                else if (d.return === `now_bare`) {
                    // Compliance without trust — Common Error 5. Stops the clock, spends the relationship.
                    deescDelta += 16; trustDelta -= 18; coachKey = `coach_r4_bare`;
                } else if (d.return === `afternoon`) {
                    deescDelta += 4; hoursThisRound += 1.5; coachKey = `coach_r4_afternoon`;
                }

                if (d.comms === `joint`) { trustDelta += 10; deescDelta += 6; }
                else if (d.comms === `press`) { trustDelta -= 8; deescDelta -= 4; coachKey = `coach_r4_press`; }
                else if (d.comms === `oem`) { deescDelta += 3; trustDelta -= 2; }

                // The team's own calm under the deadline updates self-reg directly.
                selfregDelta += Math.round((d.selfmgmt - 60) / 6);
                summaryKey = (d.relocation === `joint` && d.return === `now_process` && d.comms === `joint`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Self-regulation modulates how well good/bad moves register (secure base amplifies).
            if (deescDelta > 0) deescDelta = Math.round(deescDelta * calmFactor);
            if (trustDelta > 0) trustDelta = Math.round(trustDelta * calmFactor);

            // Apply deltas.
            ds.deescalation = Math.max(0, Math.min(100, ds.deescalation + deescDelta));
            ds.trust = Math.max(0, Math.min(100, ds.trust + trustDelta));
            ds.selfreg = Math.max(0, Math.min(100, ds.selfreg + selfregDelta));

            // Production loss accrues while the line is down. Penalty & contagion trigger past 18h.
            ds.hoursDown = Math.round((ds.hoursDown + hoursThisRound) * 10) / 10;
            ds.productionLoss = Math.round(ds.hoursDown * this.HOURLY_LOSS * 1000) / 1000;
            if (ds.hoursDown >= 18 && !ds.penaltyTriggered) {
                ds.penaltyTriggered = true;
                ds.productionLoss = Math.round((ds.productionLoss + 1.4) * 1000) / 1000; // €1.4M OEM penalty
            }
            if (ds.hoursDown >= 24) ds.contagion = true;

            ds.deescHistory.push(ds.deescalation);
            ds.trustHistory.push(ds.trust);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 FIX A — expose the composite on the reporting paths (same weights
            // as getPerformanceSummary). Scoring math unchanged.
            var _c = Math.max(0, Math.min(100, Math.round(ds.deescalation * 0.4 + ds.trust * 0.35 + ds.selfreg * 0.25)));
            ds.score = _c;
            ds.performance = { overallScore: _c };
            return {
                period: state.currentPeriod,
                score: _c,
                overallScore: _c,
                deescalation: ds.deescalation,
                deescDelta: deescDelta,
                trust: ds.trust,
                trustDelta: trustDelta,
                selfreg: ds.selfreg,
                hoursDown: ds.hoursDown,
                productionLoss: ds.productionLoss,
                penaltyTriggered: ds.penaltyTriggered,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

