        formatCompletionMessage(summary) {
            var t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            summary = summary || {};
            var score = (summary.composite != null) ? summary.composite : 0;
            var grade = summary.gradeKey ? t(summary.gradeKey) : '';
            var insights = summary.insights || [];
            var items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');
            var metric = function (label, val) {
                return '<div class="oh-completion-metric"><span>' + label + '</span><strong>' + val + '</strong></div>';
            };
            var metrics = ''
                + metric(t('comp_deesc_label'), (summary.deescalation != null ? summary.deescalation : '-'))
                + metric(t('comp_trust_label'), (summary.trust != null ? summary.trust : '-'))
                + metric(t('comp_selfreg_label'), (summary.selfreg != null ? summary.selfreg : '-'))
                + metric(t('comp_loss_label'), '\u20ac' + (summary.productionLoss != null ? summary.productionLoss : '-') + 'm');
            return ''
                + '<div class="oh-completion">'
                +   '<div class="oh-completion-heading">' + t('comp_heading') + '</div>'
                +   '<div class="oh-completion-verdict">' + grade + '</div>'
                +   '<div class="oh-completion-score">' + t('comp_score_label') + ': <strong>' + score + '</strong> / 100</div>'
                +   '<div class="oh-completion-metrics">' + metrics + '</div>'
                +   (items ? '<ul class="oh-completion-insights">' + items + '</ul>' : '')
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const deesc = ds.deescalation, trust = ds.trust, selfreg = ds.selfreg, loss = ds.productionLoss;

            // Returned-to-work requires real de-escalation; durable outcome also requires trust.
            const returned = deesc >= 60;
            const durable = returned && trust >= 60;
            const composite = Math.round(deesc * 0.4 + trust * 0.35 + selfreg * 0.25);

            let performance = `Hostage`;
            if (durable && composite >= 72) performance = `Secure Base`;
            else if (returned && composite >= 58) performance = `De-escalated`;
            else if (composite >= 42) performance = `Fragile`;

            const insights = [];
            if (durable) {
                insights.push(window.mySimulation.t(`insight_durable`));
            } else if (returned) {
                insights.push(window.mySimulation.t(`insight_compliance`));
            } else {
                insights.push(window.mySimulation.t(`insight_standoff`));
            }
            if (ds.penaltyTriggered) insights.push(window.mySimulation.t(`insight_penalty`));
            if (ds.contagion) insights.push(window.mySimulation.t(`insight_contagion`));
            if (selfreg < 45) insights.push(window.mySimulation.t(`insight_selfreg`));
            if (trust < 40) insights.push(window.mySimulation.t(`insight_lowtrust`));

            const _gk = (durable && composite >= 72) ? 'grade_securebase' : (returned && composite >= 58) ? 'grade_deescalated' : (composite >= 42) ? 'grade_fragile' : 'grade_hostage';
            if (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) {
                window.mySimulation.state.domainState.score = composite;
                window.mySimulation.state.domainState.performance = { overallScore: composite, grade: window.mySimulation.t(_gk) };
            }
            return {
                score: composite,
                gradeKey: _gk,
                deescalation: deesc,
                trust: trust,
                selfreg: selfreg,
                productionLoss: loss,
                composite: composite,
                performance: performance,
                returned: returned,
                durable: durable,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.penaltyTriggered) return window.mySimulation.t(`hint_penalty`);
            if (results.trustDelta < -8) return window.mySimulation.t(`hint_trust_drop`);
            if (ds.selfreg < 40) return window.mySimulation.t(`hint_selfreg`);
            if (ds.trust < 50 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_unbonded`);
            if (ds.deescalation >= 70) return window.mySimulation.t(`hint_strong`);
            return null;
        }

